def policy(obs, P):
    x = obs[0]
    y = obs[1]
    vx = obs[2]
    vy = obs[3]
    angle = obs[4]
    ang_v = obs[5]
    leg_left = obs[6]
    leg_right = obs[7]
    if angle > P['a_pos']:
        return 1
    if angle < P['a_neg']:
        return 3
    target = -P['k_x']*x - P['k_vx']*vx
    err = angle - target
    if err > P['a_thresh']:
        return 1
    if err < -P['a_thresh']:
        return 3
    if ang_v > P['av_pos']:
        return 1
    if ang_v < P['av_neg']:
        return 3
    if vy < P['vy_thresh']:
        return 2
    return 0
